import {glossary} from './localization.js';
import {matchesResearch,researchLabel,locationDetails,researchSummary} from './locations.js';
import {config,gameId,clone,isDone,count,nextStep,edit,undoEdit,envelope,importData,differences,applyDifferences} from './model.js';
const source=import.meta.url.includes('/dist/');
const {createChineseText}=await import(new URL(source?'../../../shared/chinese-text.js':'../../shared/chinese-text.js',import.meta.url));
const chinese=createChineseText(glossary);let searchIndex=new Map();
const {createStore}=await import(new URL(source?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={roadmap:'遊玩路線',collections:'查漏清單',trophies:'PS4 獎盃',advice:'小訣竅與資料'};
const kinds={sideQuest:'支線',dungeon:'地城',spell:'法術',equipment:'裝備',goldChest:'金箱',key:'鑰匙',royalArt:'Royal Arts',location:'劇情地點'};
const params=()=>new URL(location.href).searchParams,view=()=>Object.hasOwn(names,params().get('view'))?params().get('view'):'roadmap';
let data,progress,ready=false,busy=false,refreshPending=false,review,lastUndo,retry,search='',status='all',category='sideQuest',target='',area='',researchFilter='';const peeks=new Set();
const message=s=>$('feedback').textContent=s;
const store=createStore(config,{clone},()=>{if(!ready)return;if(busy){refreshPending=true;return;}refresh().catch(e=>message('更新失敗：'+e.message));});
function drainUpdates(){if(refreshPending){refreshPending=false;refresh().catch(e=>message(e.message));}}
async function refresh(){progress=await store.get();if(review&&JSON.stringify(progress)!==review.stamp){review.expired=true;$('import-status').textContent='預覽已過期，請重新比較。';gate();}render(true);}
const href=(v,extra={})=>'?'+new URLSearchParams({view:v,...extra});
const link=(v,label,extra={})=>`<a data-route href="${esc(href(v,extra))}">${esc(label)}</a>`;
const phase=()=>data.phases.find(c=>c.id===params().get('chapter'))||data.phases[0];
function inline(text){return esc(text).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'$1');}
function markdown(text){return text.split('\n').filter(Boolean).map(l=>/^#{1,3} /.test(l)?'<h3>'+inline(l.replace(/^#+ /,''))+'</h3>':'<p>'+inline(l.replace(/^- /,''))+'</p>').join('');}
const check=(group,id,label,suffix='' )=>`<label class="check"><input id="${esc(group+'-'+id+suffix)}" type="checkbox" data-group="${group}" data-id="${esc(id)}" ${isDone(progress,group,id)?'checked':''}><span>${esc(label)}</span></label>`;
const options=(rows,value)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
const normalize=v=>String(v).toLowerCase().replace(/[’'\s-]/g,'');
const match=(r,g)=> matchesResearch(r,researchFilter)&&(!target||target===r.id)&&(!search||normalize(searchIndex.get(r.id)||JSON.stringify(r)).includes(normalize(search)))&&(!area||area===(r.part||r.regionId||r.locationText.split(/[；／]/)[0]))&&(status==='all'||isDone(progress,g,r.id)===(status==='done'));
function toolbar(){return `<div class="toolbar"><label>搜尋中文、原名、別名、地標或 ID<input id="search" type="search" value="${esc(search)}" placeholder="例如 療癒之爪、Healpaw、金鑰匙"></label><label>顯示<select id="status">${options([['pending','未完成'],['all','全部'],['done','已完成']],status)}</select></label><button data-reset>重設條件</button></div>`;}
const empty=()=>'<p class="empty">沒有符合目前條件的項目。<button data-reset>清除條件</button></p>';
const entity=id=>data.entities.find(e=>e.id===id);
const sources=ids=>'<div class="related">'+ids.map(id=>link('advice',id,{target:'source-'+id})).join('')+'</div>';
function entityRow(r,embedded=false){const suffix=typeof embedded==='string'?'--'+embedded:'';const done=isDone(progress,'entities',r.id);const content=`${r.acquisitionRoutes?'':'<p>'+inline(r.locationText)+'</p>'}${r.tip?'<p>'+inline(r.tip)+'</p>':''}${r.level?'<p>參考等級 '+esc(r.level)+'；以主線解鎖與戰力為準。</p>':''}${locationDetails(r,{data,esc,inline,link,sources,check,suffix})}${r.aliases.length?'<p>別名：'+esc(r.aliases.join('、'))+'</p>':''}<div class="related">${r.relatedEntityIds.map(id=>{const e=entity(id);return link('collections',e.name,{category:e.kind,target:e.id});}).join('')}</div>${sources(r.sources)}`;
return `<article class="row entity-row ${done?'done':''}" id="entry-${r.id}${suffix}">${check('entities',r.id,r.name,suffix)}<div class="entity-meta">${esc(kinds[r.kind])}${researchLabel(r)?' · '+esc(researchLabel(r)):''}${r.part?' · '+esc(r.part):''}${r.scope==='free-update'?' · 免費更新／白金不強制':''}</div>${embedded?`<div class="row-body" ${!done||peeks.has(r.id)?'':'hidden'}>${content}</div>${done?`<button data-peek="${r.id}">回看詳情</button>`:''}`:`<details id="detail-${r.id}"><summary>${esc(r.locationText)}</summary>${content}${routeLink(r.id)}</details>`}</article>`;}
function routeLink(id){const s=data.steps.find(s=>s.relatedEntityIds.includes(id));return s?link('roadmap','查看相關路線',{chapter:s.phaseId,target:s.id}):'';}
function stats(){const entries=[['trophies','實際跳盃',count(progress,'trophies',data.trophies),20],['sideQuest','具名支線',completed('sideQuest'),67],['dungeon','基準地城索引',completed('dungeon'),73],['spell','已學法術',completed('spell'),12],['equipment','基準裝備參考',data.entities.filter(r=>r.kind==='equipment'&&r.scope==='base-reference'&&isDone(progress,'entities',r.id)).length,101]];return '<section class="stats" aria-label="完成度">'+entries.map(([id,label,n,total])=>`<a class="stat-card" data-route href="${href(id==='trophies'?'trophies':'collections',{category:id})}"><span>${label}</span><strong>${n} <small>/ ${total}</small></strong><span>${Math.round(n/total*100)}%</span><progress value="${n}" max="${total}" aria-label="${label}"></progress></a>`).join('')+'</section>';}
const completed=kind=>data.entities.filter(e=>e.kind===kind&&isDone(progress,'entities',e.id)).length;
function stepRow(r){const done=isDone(progress,'steps',r.id),expanded=!done||peeks.has(r.id);return `<article class="row ${done?'done':''}" id="entry-${r.id}">${check('steps',r.id,r.code+' · '+r.label)}${done?`<button data-peek="${r.id}">${expanded?'收合內容':'回看內容'}</button>`:''}${r.code==='D02'?'<p class="warning">這段可延後；打得吃力先推 D03／E，再回來。Hidden Key → Hidden Cave → 三個 Mimics → Golden Key。</p>':''}<div class="row-body" ${expanded?'':'hidden'}>${r.instructions.map(t=>'<p>'+inline(t)+'</p>').join('')}${sources(r.sources)}</div>${r.relatedEntityIds.length?'<div class="embedded"><h3>順路核對 · 各項獨立記錄</h3>'+r.relatedEntityIds.map(id=>entityRow(entity(id),r.id)).join('')+'</div>':''}</article>`;}
function road(){const c=phase(),n=nextStep(progress,data);return `<p class="eyebrow">CAT QUEST II · 雙王白金手冊</p><div class="page-heading"><div><h1>遊玩路線</h1><p>從貓國海岸到兩國收復。PS5 執行 PS4 版，本體 20 座獎盃。</p></div><button class="primary" id="continue">繼續下一步</button></div>${stats()}<p class="summary-note">參考清單完成度與遊戲回報分開。步驟、清洞、物品取得與 PSN 跳盃各自確認。</p><h2 class="chapter-title">${esc(c.label)}</h2><p>目前下一步：${esc(n?.label||'路線完成，繼續核對獎盃。')}</p><p class="warning">清洞需開箱並核對入口狀態；有水行也可能仍需任務鑰匙。通關後以 Continue 掃尾，不必開 NG+。</p>${toolbar()}${data.steps.filter(s=>s.phaseId===c.id&&match(s,'steps')).map(stepRow).join('')||empty()}<h2>回鍋備忘</h2><label for="return-note">下次從哪裡繼續</label><textarea id="return-note" maxlength="1000">${esc(progress.settings.returnNote?.value||'')}</textarea>`;}
function collections(){const list=data.entities.filter(e=>e.kind===category),areas=[...new Set(list.map(r=>r.part||r.regionId||r.locationText.split(/[；／]/)[0]))];return `<h1>查漏清單</h1><p>對照背包與遊戲計數逐項確認；勾選不會代填獎盃。</p><div class="collection-tabs">${Object.entries(kinds).filter(([k])=>k!=='location').map(([k,v])=>`<a data-route href="${href('collections',{category:k})}" ${category===k?'aria-current="page"':''}>${v}</a>`).join('')}</div><h2>${esc(kinds[category]||'支線')} · 收錄 ${list.length} 項</h2>${category==='equipment'?'<p class="warning">101 個基準項目＋7 個更新項目，不代表世界裝備總量；白金要求101件不同裝備，未核實出處不填假位置。</p>':category==='goldChest'?'<p class="warning">22 個文字定位索引，不是全金箱世界總數。全部需 Golden Key；開箱不自動勾裝備。</p>':''}<p class="research-coverage">${esc(researchSummary(data,category))}</p>${toolbar()}${researchToolbar()}<label>區域／部位 <select id="area">${options([['','全部區域／部位'],...areas.map(a=>[a,a])],area)}</select></label>${list.filter(r=>match(r,'entities')).map(r=>entityRow(r)).join('')||empty()}`;}
function condition(t){let n=t.kind==='level'?progress.counters.level?.value:t.kind?completed(t.kind):null;if(t.id.includes('dungeon'))n=completed('dungeon');if(t.id==='cq2-tr-royal-fur')n=['rolling','smash','water'].filter(id=>isDone(progress,'entities','cq2-art-'+id)).length;if(t.id==='cq2-tr-pawlatinum')n=data.trophies.filter(r=>r.id!==t.id&&isDone(progress,'trophies',r.id)).length;const max=t.target||(t.id==='cq2-tr-royal-fur'?3:t.id==='cq2-tr-pawlatinum'?19:null);return n!==null&&n!==undefined&&max?`<p>網站條件紀錄 ${n} / ${max} ${n>=max?'· 已達門檻，請核對實際跳盃':''}</p>`:'';}
function trophies(){return `<h1>PS4 獎盃</h1><p>PS5 相容執行 PS4 版 · 20 座（1 白金／8 金／5 銀／6 銅）。條件達標僅提醒，實際跳盃手動確認。</p><h2>遊戲回報 · 與網站具名紀錄分開</h2><div class="counter-grid">${[['level','角色等級',99],['sideQuest','遊戲支線',67],['dungeon','遊戲地城',73],['equipment','遊戲裝備',101]].map(([id,label,max])=>`<label>${label}<input id="counter-${id}" data-counter="${id}" type="number" min="0" step="1" value="${progress.counters[id]?.value??''}"><small>白金門檻 ${max}；可超標</small></label>`).join('')}</div>${toolbar()}${data.trophies.filter(r=>match(r,'trophies')).map(t=>`<article class="row" id="entry-${t.id}">${check('trophies',t.id,t.name+' · 實際已跳盃')}<div class="row-body"><span class="grade">${t.grade}</span><p>${esc(t.condition)}</p>${condition(t)}${t.kind&&t.kind!=='level'?link('collections','查看具名缺項',{category:t.kind}):''}${t.kind&&['sideQuest','dungeon','equipment'].includes(t.kind)?'<p>遊戲回報：'+(progress.counters[t.kind]?.value??'尚未填寫')+' ／網站：'+completed(t.kind)+'。有差異請逐名核對。</p>':''}</div></article>`).join('')||empty()}`;}
function advice(){return '<h1>小訣竅與資料</h1>'+translationPolicy()+'<h2>裝備與地城補查範圍</h2><p>'+esc(researchSummary(data,'equipment'))+'</p><p>'+esc(researchSummary(data,'dungeon'))+'</p><p>2026-11-27補查；單一來源、跨語對應及衝突逐項保留。沒有新增精確座標或宣稱實機驗收。</p>'+markdown(data.advice)+'<h2>額外內容</h2><p>Infinity Tomb、Mew Game 與 NG+ 不列白金必要路線。更新裝備可在查漏清單記錄；未核實世界完整總量。</p><h2>已知資料缺口</h2>'+data.gaps.map(g=>`<article class="row"><h3>${esc(g.id)}</h3><p>${esc(g.label)}</p><p>${esc(g.blocks)}</p></article>`).join('')+'<h2>來源與查證</h2><p>依 2026-11-27 提供的研究規格整理，未宣稱 PS4／PS5 遊戲實機驗收。</p>'+data.sources.map(s=>`<article class="row" id="entry-source-${s.id}"><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.id+' · '+s.label)}</a></h3><p>${esc(s.note)}</p></article>`).join('');}

function translationPolicy(){return '<section id="entry-translation-policy" class="translation-policy" tabindex="-1"><h2>中文譯名與原文對照</h2><p>'+esc(glossary.notice)+'</p><p>中文用來降低閱讀負擔；保留原文方便對照遊戲與外文攻略，兩種名稱都能搜尋。同物品沿用同一譯名與進度 ID。新譯名不代表取得地點、掉落條件或遊戲版本已核實。</p><p>目前詞彙表沒有已核對的官方中文項目。之後取得遊戲中文畫面或官方在地化證據時，優先更新顯示並保留舊譯作搜尋別名。少數專名採音譯，沒有額外推測效果。</p></section>';}

function reset(){area='';researchFilter='';search='';status=view()==='roadmap'?'all':'pending';target='';}
function render(preserve=false){const openDetails=[...document.querySelectorAll('main details[open][id]')].map(el=>el.id);const active=document.activeElement,focusId=active?.id,y=scrollY,selection=active?.type==='search'?[active.selectionStart,active.selectionEnd]:null;const old=[...document.querySelectorAll('main article')],anchor=old.find(el=>el.getBoundingClientRect().bottom>0),anchorId=anchor?.id,top=anchor?.getBoundingClientRect().top;
 $('main').innerHTML=({roadmap:road,collections,trophies,advice}[view()])();
 const readingView=view();if(readingView==='collections'||readingView==='trophies')$('main').querySelector('h1')?.insertAdjacentHTML('afterend','<p class="translation-note">名稱採本站繁中參考譯名，原文以小字對照；尚未逐項核對遊戲官方中文。<a data-route href="'+href('advice',{target:'translation-policy'})+'">譯名說明</a></p>');
 chinese.decorate($('main'));
 if(preserve)for(const id of openDetails){const el=$(id);if(el?.tagName==='DETAILS')el.open=true;}
 $('phase-navigation').innerHTML=data.phases.map(c=>`<li><a data-route href="${href('roadmap',{chapter:c.id})}" ${view()==='roadmap'&&phase().id===c.id?'aria-current="location"':''}>${esc(c.label)}${c.steps?'<small>'+c.steps.filter(id=>isDone(progress,'steps',id)).length+' / '+c.steps.length+' 步驟</small>':''}</a></li>`).join('');
 document.querySelectorAll('[data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view()?'page':'false'));
 chinese.decorate($('phase-navigation'));chinese.decorate(document.querySelector('.brand'));chinese.decorate(document.querySelector('.topbar'));
 if(target)$('main').insertAdjacentHTML('afterbegin',`<p>正在定位 ${esc(target)} <button data-reset>清除定位</button></p>`);
 if(preserve){const removed=old.findIndex(el=>el.contains(active));const neighbor=old.slice(removed+1).map(el=>$(el.id)).find(Boolean);const next=$(focusId)||(removed>=0?neighbor?.querySelector('input,button,a'):null)||$('main');next.focus({preventScroll:true});if(selection&&next.type==='search')next.setSelectionRange(...selection);const same=anchorId&&$(anchorId);scrollTo(0,same?y+same.getBoundingClientRect().top-top:y);}
}
function navigate(v,extra={}){history.pushState({},'',href(v,extra));reset();category=extra.category||'sideQuest';researchFilter=extra.research||'';target=extra.target||'';if(target)status='all';render();if(matchMedia('(max-width:720px)').matches)$('menu').open=false;requestAnimationFrame(()=>{const el=target?$('entry-'+target):null;if(el){el.scrollIntoView();(el.querySelector('input')||el).focus({preventScroll:true});}else{scrollTo(0,0);$('main').focus({preventScroll:true});}});}
async function save(g,id,value){if(busy)return;busy=true;retry=()=>save(g,id,value);try{const result=await edit(store,g,id,value,progress[g][id]?.keyRevision||0);progress=result.progress;lastUndo=result.undo;$('undo').hidden=false;$('retry').hidden=true;retry=null;message('已保存，可撤銷這一筆。');render(true);}catch(e){message('保存失敗：'+e.message+'；原資料保留，請重試。');$('retry').hidden=false;render(true);}finally{busy=false;drainUpdates();}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');try{a.href=url;a.download=name;a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
function openBackup(){$('backup-save-state').textContent='進度只保存於此瀏覽器；網站備份不是 PS5 遊戲存檔。';$('backup-dialog').showModal();}
$('backup-dialog').addEventListener('close',()=>$('open-backup').focus());
const safely=fn=>async e=>{try{await fn(e);}catch(error){message(error.message);}};
document.addEventListener('click',safely(async e=>{const a=e.target.closest('[data-route],[data-view]');if(a){e.preventDefault();const u=new URL(a.href);navigate(u.searchParams.get('view')||'roadmap',Object.fromEntries([...u.searchParams].filter(([k])=>k!=='view')));return;}const el=e.target.closest('button');if(!el)return;
 if(el.id==='open-backup'||el.hasAttribute('data-open-backup'))openBackup();
 if(el.id==='backup-close')$('backup-dialog').close();if(el.id==='import-open')$('import-file').click();
 if(el.hasAttribute('data-reset')){const u=new URL(location.href);u.searchParams.delete('target');u.searchParams.delete('research');history.replaceState({},'',u);reset();render();}
 if(el.dataset.peek){peeks.has(el.dataset.peek)?peeks.delete(el.dataset.peek):peeks.add(el.dataset.peek);render(true);}
 if(el.id==='continue'){const n=nextStep(progress,data);navigate(n?'roadmap':'collections',n?{chapter:n.chapterId,target:n.id}:{});}
 if(el.id==='export-progress')download(envelope(await store.get()),'cq2-progress.json');
 if(el.id==='export-all')download(await store.exportAll(),'cq2-recovery.json');
 if(el.id==='undo'&&lastUndo){busy=true;try{progress=await undoEdit(store,lastUndo);lastUndo=null;el.hidden=true;message('已撤銷該筆，其他紀錄保留。');render(true);}finally{busy=false;drainUpdates();}}
 if(el.id==='retry'&&retry)await retry();
}));
document.addEventListener('change',safely(async e=>{const el=e.target;if(el.dataset.group){await save(el.dataset.group,el.dataset.id,{done:el.checked});return;}if(el.dataset.counter){if(!el.value.trim()||!Number.isSafeInteger(Number(el.value))||Number(el.value)<0){message('計數須為非負整數。');return;}await save('counters',el.dataset.counter,{value:Number(el.value)});return;}
 if(el.id==='status'){status=el.value;render(true);}if(el.id==='category'){category=el.value;reset();render();}if(el.id==='area'){area=el.value;render(true);}if(el.id==='research-filter'){researchFilter=el.value;render(true);}if(el.id==='return-note'){await save('settings','returnNote',{value:el.value});}
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];$('backup-dialog').close();try{await preview(file);}finally{el.value='';}}
}));
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render(true);}});
window.addEventListener('popstate',()=>{reset();category=params().get('category')||'sideQuest';researchFilter=params().get('research')||'';target=params().get('target')||'';if(target)status='all';render();});

async function preview(file){
 if(file.size>10*1024*1024)throw Error('檔案超過 10 MB，停止匯入。');const sourceRaw=await file.text(),local=await store.raw(),localRaw=JSON.stringify(local);
 await store.archive({sourceRaw,localRaw,at:new Date().toISOString(),name:file.name});
 const incoming=importData(JSON.parse(sourceRaw));review={sourceRaw,localRaw,stamp:localRaw,rows:differences(local,incoming),downloaded:false,expired:false};
 $('diff-rows').innerHTML=review.rows.map((r,i)=>`<div class="diff-row"><label class="check"><input type="checkbox" data-diff="${i}" ${r.missing?'disabled':''}><span>${esc(r.group+' / '+r.id)}${r.missing?' · 來源缺少，保留本機':r.older?' · 來源較舊，需額外核對':''}</span></label><pre>本機：${esc(JSON.stringify(r.local)??'無紀錄')}\n來源：${esc(JSON.stringify(r.incoming)??'無紀錄')}</pre></div>`).join('')||'<p>兩端紀錄相同。</p>';
 $('import-status').textContent=review.rows.length+' 筆差異，未勾選項目保留本機。';$('import-ack').checked=false;$('import-ack').disabled=true;$('older-ack').checked=false;gate();$('import-dialog').showModal();
}
function gate(){$('import-apply').disabled=!review||review.expired||!review.downloaded||!$('import-ack').checked;}
$('choose-source').onclick=()=>document.querySelectorAll('[data-diff]:not(:disabled)').forEach(x=>x.checked=true);
$('choose-local').onclick=()=>document.querySelectorAll('[data-diff]').forEach(x=>x.checked=false);
$('download-recovery').onclick=async()=>{try{if(review.expired)throw Error('預覽已過期');download({gameId,recoveryBundle:{localRaw:review.localRaw,sourceRaw:review.sourceRaw},progress:JSON.parse(review.localRaw)},'cq2-before-import.json');review.downloaded=true;$('import-ack').disabled=false;$('import-status').textContent='備份已開始下載，請確認檔案保存後勾選。';}catch(e){review.downloaded=false;$('import-ack').checked=false;$('import-ack').disabled=true;$('import-status').textContent='備份失敗：'+e.message;}gate();};
$('import-ack').onchange=gate;
$('import-apply').onclick=async()=>{if(!review||$('import-apply').disabled)return;const selected=new Set([...document.querySelectorAll('[data-diff]:checked')].map(el=>{const r=review.rows[Number(el.dataset.diff)];return r.group+'/'+r.id;}));busy=true;try{await store.checkpoint('匯入前');progress=await store.update(p=>applyDifferences(p,review.rows,selected,$('older-ack').checked),review.stamp);lastUndo=null;$('undo').hidden=true;review=null;$('import-dialog').close();message('已套用選定差異，原文與快照均保留。');render(true);}catch(e){$('import-status').textContent=e.message;if(e.message.includes('過期'))review.expired=true;gate();}finally{busy=false;drainUpdates();}};
$('import-close').onclick=()=>{$('import-dialog').close();review=null;};
$('import-dialog').addEventListener('close',()=>{review=null;$('open-backup').focus();});


try{const response=await fetch('./data.json',{cache:'no-store'});if(!response.ok)throw Error('攻略讀取失敗');data=await response.json();searchIndex=new Map([...data.entities,...data.steps,...data.trophies].map(r=>{const original=JSON.stringify(r);return [r.id,original+' '+chinese.plain(original)];}));if(data.gameId!==gameId||data.trophies.length!==20||data.phases.length!==6)throw Error('攻略資料不完整');progress=await store.open();ready=true;reset();category=params().get('category')||'sideQuest';researchFilter=params().get('research')||'';target=params().get('target')||'';if(target)status='all';$('menu').open=matchMedia('(min-width:721px)').matches;render();message('進度已載入，操作保存於此瀏覽器。');if(target)requestAnimationFrame(()=>$('entry-'+target)?.scrollIntoView());}catch(e){$('main').innerHTML='<h1>無法載入</h1><p>'+esc(e.message)+'</p><p>原有紀錄保留，已停止寫入。</p><button id="raw-export">下載原始封存</button>';$('raw-export').onclick=safely(async()=>download(await store.exportAll(),'cq2-original.json'));message('載入失敗：'+e.message);}

function researchToolbar(){if(!['equipment','dungeon'].includes(category))return '';const rows=category==='equipment'?[['','全部取得來源'],['named','具名來源'],['pool','僅候選池'],['uncertain','有待核實對應']]:[['','全部地城'],['secret','有秘密路徑提醒'],['explored','有入口／回收提醒'],['missing','走法尚未補齊'],['uncertain','通路仍有待核實']];return '<label class="research-filter">查證範圍 <select id="research-filter">'+options(rows,researchFilter)+'</select></label>'; }
